import { CustomTooltip } from 'components/CustomTooltip';
import { Toggle } from 'components/Toggle/Toggle';
import { StyledTooltip } from 'shared/Styles';

import {
  DDTTitle,
  DDTToggleLabel,
  DDTToggleRow,
  DDTToolbar,
  DDTToolbarLeft,
  DDTUnit,
} from './DrillDownTableToolbar.styles';

interface ToggleWithTooltipProps {
  readonly checked: boolean;
  readonly onCheckedChange: (checked: boolean) => void;
  readonly disabled: boolean;
  readonly ariaLabel: string;
  readonly ariaLabelledBy: string | undefined;
  readonly tooltip?: string;
}

function ToggleWithTooltip({
  checked,
  onCheckedChange,
  disabled,
  ariaLabel,
  ariaLabelledBy,
  tooltip,
}: ToggleWithTooltipProps): React.ReactElement {
  const toggle = (
    <Toggle
      checked={checked}
      onCheckedChange={onCheckedChange}
      disabled={disabled}
      ariaLabel={ariaLabel}
      ariaLabelledBy={ariaLabelledBy}
    />
  );
  if (!tooltip) return toggle;
  return (
    <CustomTooltip
      content={<StyledTooltip size="small">{tooltip}</StyledTooltip>}
    >
      {toggle}
    </CustomTooltip>
  );
}

export interface DrillDownTableToolbarProps {
  readonly title: string;
  readonly unit?: string;
  readonly compareLabel?: string;
  readonly compareTooltip?: string;
  readonly compareDisabled?: boolean;
  readonly compareChecked?: boolean;
  readonly onCompareChange?: (checked: boolean) => void;
  readonly dataTestId?: string;
}

export const DrillDownTableToolbar: React.FC<DrillDownTableToolbarProps> = ({
  title,
  unit,
  compareLabel,
  compareTooltip,
  compareDisabled = false,
  compareChecked = false,
  onCompareChange,
  dataTestId,
}) => {
  const testId = (suffix: string) =>
    dataTestId ? `${dataTestId}-${suffix}` : undefined;

  return (
    <DDTToolbar data-testid={testId('toolbar')}>
      <DDTToolbarLeft>
        <DDTTitle data-testid={testId('title')}>{title}</DDTTitle>
        {unit && <DDTUnit data-testid={testId('unit')}>{unit}</DDTUnit>}
      </DDTToolbarLeft>

      {compareLabel && onCompareChange && (
        <DDTToggleRow>
          <ToggleWithTooltip
            checked={compareChecked}
            onCheckedChange={onCompareChange}
            disabled={compareDisabled}
            ariaLabel={compareLabel}
            ariaLabelledBy={testId('compare-label')}
            tooltip={compareTooltip}
          />
          <DDTToggleLabel id={testId('compare-label')}>
            {compareLabel}
          </DDTToggleLabel>
        </DDTToggleRow>
      )}
    </DDTToolbar>
  );
};
